solutionCode:
let fileSizeMB = 80;
let networkSpeedMbps = 64;
let actualSpeedMBps = networkSpeedMbps / 8;
console.log("السرعة الفعلية: " + actualSpeedMBps + " MB/s");
let secondsNeeded = fileSizeMB / actualSpeedMBps;
console.log("زمن التنزيل المقدر: " + secondsNeeded + " ثانية");
